            return self._user_cache[user_id]
        # Would query database here
        return {'user_id': user_id, 'created_at': '2024-01-01', 'status': 'active'}

    def update_user_preference(self, user_id: str, key: str, value: Any) -> bool:
        """Store user preference for future sessions."""
        logger.info(f'Updating preference {key} for user {user_id}')
        if user_id not in self._user_cache:
            self._user_cache[user_id] = self.get_profile(user_id)
