Now I realize the ConfigLoader class might not be handling the features section correctly when environment variables are involved. Can you check /tmp/project/src/config_loader.py and add support for a CACHE_ENABLED environment variable override? It should work the same way as the existing API_BASE_URL override — if the env var is set to 'true' or '1', it should enable caching regardless of what's in the YAML file. Make sure to handle the string-to-boolean conversion properly.

import os
import yaml
from pathlib import Path
from typing import Dict, Any

class ConfigLoader:
    DEFAULT_CONFIG_PATH = Path(__file__).parent.parent / 'config' / 'settings.yaml'

    @classmethod
    def load(cls, config_path: str = None) -> Dict[str, Any]:
        path = Path(config_path) if config_path else cls.DEFAULT_CONFIG_PATH

        if not path.exists():
            raise FileNotFoundError(f"Config file not found: {path}")

        with open(path, 'r') as f:
            config = yaml.safe_load(f)

        # Override with environment variables
        config = cls._apply_env_overrides(config)
        return config

    @classmethod
    def _apply_env_overrides(cls, config: Dict[str, Any]) -> Dict[str, Any]:
        if os.environ.get('API_BASE_URL'):
            config.setdefault('api', {})['base_url'] = os.environ['API_BASE_URL']
        if os.environ.get('LOG_LEVEL'):
            config.setdefault('logging', {})['level'] = os.environ['LOG_LEVEL']
        return config

