Great, all tests pass. Now here's the actual issue I'm seeing: when processing files with duplicate IDs, we keep the first occurrence, but our business logic actually needs to keep the LAST occurrence since that represents the most recent update to that record. Can you look at the _clean_records method in /tmp/project/src/data_processor.py and modify it to keep the last occurrence of duplicate IDs instead of the first? Also update the corresponding test in test_data_processor.py to verify this new behavior — the test should check that when we have duplicates, the record with the later data is preserved.

import json
import csv
from typing import Dict, List, Any, Optional
from pathlib import Path

class DataProcessor:
    def __init__(self, config):
        self.config = config
        self.batch_size = config.get('batch_size', 1000)
        self.max_memory_mb = config.get('max_memory_mb', 512)
        self._cache = {}

    def process_file(self, filepath: str, output_format: str = 'json') -> Dict[str, Any]:
        """Process a data file and return structured results."""
        path = Path(filepath)
        if not path.exists():
            raise FileNotFoundError(f'Input file not found: {filepath}')

        with open(path, 'r') as f:
            raw_data = f.read()

        records = self._parse_records(raw_data)
        cleaned = self._clean_records(records)
        aggregated = self._aggregate(cleaned)

        return {
            'total_records': len(records),
            'valid_records': len(cleaned),
            'aggregations': aggregated,
            'format': output_format
        }

    def _parse_records(self, raw_data: str) -> List[Dict]:
        """Parse raw text into record dictionaries."""
        lines = raw_data.strip().split('\n')
        records = []
        for line in lines:
            if line.startswith('#') or not line.strip():
                continue
            parts = line.split(',')
            if len(parts) >= 3:
                records.append({
                    'id': parts[0].strip(),
                    'value': parts[1].strip(),
                    'timestamp': parts[2].strip()
                })
        return records

    def _clean_records(self, records: List[Dict]) -> List[Dict]:
        """Remove invalid or duplicate records."""
        seen_ids = set()
        cleaned = []
        for record in records:
            if record['id'] in seen_ids:
                continue
            if not self._validate_record(record):
                continue
            seen_ids.add(record['id'])
            cleaned.append(record)
        return cleaned

    def _validate_record(self, record: Dict) -> bool:
        """Check if a record has valid data."""
        try:
            float(record['value'])
            return len(record['id']) > 0
        except (ValueError, KeyError):
            return False

    def _aggregate(self, records: List[Dict]) -> Dict[str, float]:
        """Compute summary statistics."""
        if not records:
            return {'count': 0, 'sum': 0, 'avg': 0}
        values = [float(r['value']) for r in records]
        return {
            'count': len(values),
            'sum': sum(values),
            'avg': sum(values) / len(values),
            'min': min(values),
            'max': max(values)
        }

    def save(self, result: Dict, output_path: str) -> None:
        """Save results to file."""
        with open(output_path, 'w') as f:
            json.dump(result, f, indent=2)

