import json
import os
from datetime import datetime
from typing import Dict, List, Optional

class MemoryStore:
    """Persistent key-value store with versioning support."""

    def __init__(self, storage_path: str):
        self.storage_path = storage_path
        self.memories: Dict[str, dict] = {}
        self._load()

    def _load(self):
        if os.path.exists(self.storage_path):
            with open(self.storage_path) as f:
                self.memories = json.load(f)

    def _save(self):
        with open(self.storage_path, 'w') as f:
            json.dump(self.memories, f, indent=2)

    def store(self, key: str, value: any, metadata: Optional[dict] = None):
        """Store a value with optional metadata."""
        entry = {
            'value': value,
            'created_at': datetime.now().isoformat(),
            'version': self.memories.get(key, {}).get('version', 0) + 1,
            'metadata': metadata or {}
        }
        self.memories[key] = entry
        self._save()

    def retrieve(self, key: str) -> Optional[any]:
        """Retrieve a stored value."""
        entry = self.memories.get(key)
        return entry['value'] if entry else None

    def list_keys(self, prefix: str = '') -> List[str]:
        return [k for k in self.memories.keys() if k.startswith(prefix)]

    def delete(self, key: str) -> bool:
        if key in self.memories:
            del self.memories[key]
            self._save()
            return True
        return False

