import hashlib
import os
from typing import Dict, List, Optional

USER_ROLES = {
    'admin': ['read', 'write', 'delete', 'admin'],
    'editor': ['read', 'write'],
    'viewer': ['read']
}

USERS_DB = {
    'user_001': {'role': 'viewer', 'name': 'Alice'},
    'user_002': {'role': 'editor', 'name': 'Bob'},
    'admin_001': {'role': 'admin', 'name': 'Charlie'}
}

def authenticate_user(username: str, password: str) -> Optional[str]:
    """Authenticate user and return user_id if successful."""
    password_hash = hashlib.sha256(password.encode()).hexdigest()
    # In production, compare against stored hash
    for user_id, user_data in USERS_DB.items():
        if user_data['name'].lower() == username.lower():
            return user_id
    return None

def get_user_permissions(user_id: str) -> Dict[str, List[str]]:
    """Get permissions for a user based on their role."""
    if user_id not in USERS_DB:
        return {}
    role = USERS_DB[user_id]['role']
    permissions = USER_ROLES.get(role, [])
    return {'files': permissions, 'settings': permissions}

def check_admin_access(user_id: str) -> bool:
