def cleanup_stale_workers(patterns=['python', 'node', 'java']):
    terminated = []
    for pattern in patterns:
        pids = get_process_list(pattern)
        for pid in pids:
            try:
                os.kill(pid, signal.SIGKILL)
                terminated.append((pattern, pid))
            except ProcessLookupError:
                pass
    return terminated
