import time
import hashlib
from typing import Optional, Tuple
from dataclasses import dataclass
from functools import wraps

import jwt
import redis

@dataclass
class AuthConfig:
    secret_key: str
    token_expiry: int = 3600
    refresh_expiry: int = 86400
    rate_limit_window: int = 300
    max_failed_attempts: int = 5

class TokenValidator:
    def __init__(self, config: AuthConfig):
        self.config = config
        self._cache = {}

    def validate(self, token: str) -> Tuple[bool, Optional[dict]]:
        try:
            payload = jwt.decode(
                token, 
                self.config.secret_key, 
                algorithms=['HS256']
            )
            if payload.get('exp', 0) < time.time():
                return False, None
            return True, payload
        except jwt.InvalidTokenError as e:
            return False, None

    def refresh_token(self, refresh_token: str) -> Optional[str]:
        valid, payload = self.validate(refresh_token)
        if not valid or payload.get('type') != 'refresh':
            return None

        new_payload = {
            'user_id': payload['user_id'],
            'exp': time.time() + self.config.token_expiry,
            'type': 'access'
        }
        return jwt.encode(new_payload, self.config.secret_key, algorithm='HS256')

class RateLimiter:
    def __init__(self, redis_client: redis.Redis, config: AuthConfig):
        self.redis = redis_client
        self.config = config

    def _get_key(self, identifier: str) -> str:
        return f"ratelimit:auth:{hashlib.md5(identifier.encode()).hexdigest()}"

    def is_blocked(self, identifier: str) -> bool:
        key = self._get_key(identifier)
        attempts = self.redis.get(key)
        if attempts and int(attempts) >= self.config.max_failed_attempts:
            return True
        return False

    def record_failure(self, identifier: str) -> None:
        key = self._get_key(identifier)
        pipe = self.redis.pipeline()
        pipe.incr(key)
        pipe.expire(key, self.config.rate_limit_window)
        pipe.execute()

    def clear(self, identifier: str) -> None:
        self.redis.delete(self._get_key(identifier))

class AuthMiddleware:
    def __init__(self, config: AuthConfig, redis_client: redis.Redis):
        self.validator = TokenValidator(config)
        self.limiter = RateLimiter(redis_client, config)
        self.config = config

    def authenticate(self, request):
        client_ip = request.remote_addr

        if self.limiter.is_blocked(client_ip):
            return {'error': 'Too many failed attempts'}, 429

        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            self.limiter.record_failure(client_ip)
            return {'error': 'Missing token'}, 401

        valid, payload = self.validator.validate(token)
        if not valid:
            self.limiter.record_failure(client_ip)
            return {'error': 'Invalid token'}, 401

        self.limiter.clear(client_ip)
        request.user = payload
        return None

def require_auth(middleware: AuthMiddleware):
    def decorator(f):
        @wraps(f)
        def wrapped(request, *args, **kwargs):
            error = middleware.authenticate(request)
            if error:
                return error
            return f(request, *args, **kwargs)
        return wrapped
    return decorator

