import pwd

class PermissionManager:
    ADMIN_GROUPS = ['wheel', 'sudo', 'admin']

    def __init__(self, user=None):
        self.user = user or os.getenv('APP_USER', 'appuser')

    def check_admin_access(self):
        try:
            user_groups = [g.gr_name for g in grp.getgrall() if self.user in g.gr_mem]
            return any(g in self.ADMIN_GROUPS for g in user_groups)
        except KeyError:
            return False

    def get_effective_permissions(self):
        return {
            'uid': os.getuid(),
            'gid': os.getgid(),
            'groups': os.getgroups()
        }

